import itertools

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def generate_all_strings(n):
    return ["".join(map(str, p)) for p in itertools.product([0, 1], repeat=n)]

def hamming_sphere(s, n, k):
    sphere = []
    for s_prime in generate_all_strings(n):
        if hamming_distance(s, s_prime) == k:
            sphere.append(s_prime)
    return frozenset(sphere)

# Test case: n=5, k=2 (since 5 > 2*2)
n = 5
k = 2
all_strings = generate_all_strings(n)
spheres = {}

# Calculate and store the sphere for every possible leader string
for s_leader in all_strings:
    sphere = hamming_sphere(s_leader, n, k)

    # Check if this sphere has been seen before
    if sphere in spheres:
        # Ambiguity found! The current s_leader shares a sphere with spheres[sphere]
        s_known = spheres[sphere]
        print(f"Ambiguity found for n={n}, k={k}!")
        print(f"Sphere generated by S_A = {s_known}")
        print(f"Same sphere generated by S_B = {s_leader}")
        break
    else:
        spheres[sphere] = s_leader

if len(spheres) == len(all_strings):
    print(f"No ambiguity found for n={n}, k={k}. Max ambiguity M=1.")

