import itertools
import numpy as np

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

N = 6
K = 2

# Generate all 2^N strings
all_strings = [''.join(map(str, p)) for p in itertools.product([0, 1], repeat=N)]

def get_sphere(S, k):
    sphere = set()
    for T in all_strings:
        if hamming_distance(S, T) == k:
            sphere.add(T)
    return sphere

# Dictionary to store which strings produce which spheres
sphere_map = {}
for S in all_strings:
    sphere = frozenset(get_sphere(S, K))
    if sphere not in sphere_map:
        sphere_map[sphere] = []
    sphere_map[sphere].append(S)

# Find the maximum ambiguity M
M_max = 0
for sphere, candidates in sphere_map.items():
    M_max = max(M_max, len(candidates))

print(f"N={N}, K={K}. Maximum ambiguity M = {M_max}")

